components/gordonbyte/common/announcment:
{{#if theme_settings.gb-top-bar-enable }}
<div class="topBar{{#if theme_settings.gb-animation-enable }} gb-animate-me animate__animated{{/if}}" {{#if theme_settings.gb-animation-enable }}data-animation="fadeIn"{{/if}}>

        {{#if theme_settings.gb-bar-type '==' 3 }}
        <div class="topMenu textLeft">
          <ul>
            {{#each pages}}
                 <li class="navPages-item navPages-item-page">
                     <a class="navPages-action{{#if name '==' ../page.title}} activePage{{/if}}"
                        href="{{url}}"
                        aria-label="{{name}}"
                     >
                         {{name}}
                     </a>
                 </li>
             {{/each}}
           </ul>
        </div><!---.topMenu ends-->
        {{/if}}

        {{#or (if theme_settings.gb-bar-type '==' 1) (if theme_settings.gb-bar-type '==' 2 ) }}
        <div class="anncmnt {{#if theme_settings.gb-bar-type '==' 1 }}textCenter{{else}}textLeft{{/if}}">
           
           <div>{{ theme_settings.gb-announcement-text }}</div>
                   <div class="main-nav">
                    <!--COMING SOON -->
                    {{#or (if theme_settings.logo-position '===' 'searchleft') (if theme_settings.logo-position '===' 'searchcenter')}}
                        {{> components/gordonbyte/common/quick-search2 name='nav-quick-search'}}
                    {{/or}}
        
                    {{#or (if theme_settings.logo-position '===' 'left') (if theme_settings.logo-position '===' 'center')}}
                    <div class="main-nav-menuList">
                        <ul> 
                          {{#each pages}}
                            {{!-- prevent to show specific pages   --}}
                            {{#inArray (split 'shipping-returns|resources' '|') (lowercase (dashcase name))}}
                             
                            {{else}}
                               <li class="navPages-item navPages-item-page">
                                   <a class="navPages-action{{#if name '==' ../page.title}} activePage{{/if}}"
                                      href="{{url}}"
                                      aria-label="{{name}}"
                                   >
        						   	{{first (split name ' - ')}}
                                   </a>
        
                               </li>
                            {{/inArray}}
                           {{/each}}
                                <li class="navPages-item navPages-item-page">
                                    {{#if customer}}
                                        <a class="navPages-action" href="/logout.php" aria-label="Sign Out">
                                            Sign Out
                                        </a>
                                    {{else}}
                                        <a class="navPages-action" href="/login.php" aria-label="Sign In">
                                            Sign In
                                        </a>
                                    {{/if}}
                                </li>

                         </ul>
                      </div><!--.main-nav-menuList ends-->
                    {{/or}}
                </div>
        </div><!---.anncmnt ends-->
        {{/or}}

        {{#or (if theme_settings.gb-bar-type '==' 2 ) (if theme_settings.gb-bar-type '==' 3 ) }}
        <div class="companyInfo text-right">

            {{#if theme_settings.gb-top-bar-store-number}}
            <div class="companyInfo-phone">
              <svg height="15" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 306.59 306.55">
                <path d="M85.24,6c4.6,1.57,9.14,3.49,11.33,8.11a24.56,24.56,0,0,1,2.59,9.64A209.15,209.15,0,0,0,109,84c2.19,6.79.17,12.76-4.84,17.77-11.63,11.66-23.22,23.36-34.89,35-1.42,1.4-1.78,2.39-.77,4.29q38,71.46,109.61,109.09c.44.23.9.43,2.06,1a17.12,17.12,0,0,1,1.77-2.51c11.33-11.4,22.73-22.72,34-34.16,5.62-5.69,12-7.34,19.65-4.88a195.67,195.67,0,0,0,56.15,9.32,33.49,33.49,0,0,1,10.77,1.87c5.46,2,8,6.91,9.68,12.19v65.87a7.1,7.1,0,0,0-.58,1c-3,8.71-8.79,13-18,12.72s-18.16-.53-27.19-1.4A282.09,282.09,0,0,1,197,295.47,288,288,0,0,1,89.3,226.59a287.09,287.09,0,0,1-61.94-93.36A289.26,289.26,0,0,1,5.61,24.57c-.07-7.7,3-13.49,10-17C16.81,7,18.11,6.53,19.37,6Z" transform="translate(-5.61 -6)"/>
              </svg>
              {{#if settings.phone_number.length '>' 1}}
                <span><a href="tel:{{ settings.phone_number }}" aria-label="Store number {{ settings.phone_number }}">{{lang 'announcement.phone'}}</a></span>
                <span class="companyInfo-mobile"><a href="tel:{{ settings.phone_number }}" aria-label="Store number {{ settings.phone_number }}">{{lang 'announcement.phone'}}</a></span>
              {{else}}
                {{#if theme_settings.gb-theme-demo}}
                  <span><a href="tel:#" aria-label="Store number placeholder">{{lang 'announcement.phone'}}</a></span>
                  <span class="companyInfo-mobile"><a href="#" aria-label="Store number placeholder">{{lang 'announcement.phone'}}</a></span>
                {{/if}}
              {{/if}}
            </div><!---.companyInfo-phone ends-->
            {{/if}}

            {{#if theme_settings.gb-top-bar-store-location}}
            <div class="companyInfo-loc">
                <svg height="15" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 274.64 384.38">
                  <path d="M154.59,5.54c7,1.19,14.1,2,21,3.64C218,19.52,248.64,44.83,267.74,83.67c19.89,40.44,18.51,81.58,1.31,122.65-9.33,22.29-22.32,42.45-36.56,61.82-17.7,24.08-36,47.71-53.26,72.12-10,14.15-18.44,29.41-27.45,44.25-1.7,2.79-3.21,5.43-6.93,5.41-3.54,0-5.2-2.43-6.65-5.22-16.16-31.08-36.83-59.18-57.6-87.22-16.52-22.31-33.31-44.43-47.14-68.59-11.37-19.86-20.68-40.6-24-63.42C2.14,115.41,17.29,73.07,54.94,39.3c22-19.7,48.16-30.46,77.6-33.14a15.06,15.06,0,0,0,2.53-.62ZM216.9,142.88A72,72,0,1,0,145.19,215,72.09,72.09,0,0,0,216.9,142.88Z" transform="translate(-7.67 -5.54)"/>
                </svg>
                <span><a target="_blank" rel="noopener" href="http://maps.google.com/maps?q={{ settings.address }}" aria-label="{{ settings.address }}">{{lang 'announcement.location'}}</a></span>
                <span class="companyInfo-mobile"><a target="_blank" rel="noopener" href="http://maps.google.com/maps?q={{ settings.address }}" aria-label="{{ settings.address }}">{{lang 'announcement.location'}}</a></span>
            </div><!---.companyInfo ends-->
            {{/if}}

        </div><!---.companyInfo ends-->
        {{/or}}

</div><!--topBar ends-->
{{/if}}
